\begin{document}
\title{\textbf{Two Hypotheses for Arithmetic Progressions}}
\author{C.\ Lando Mills\\
Trabuco Canyon, California\\
\texttt{c.landonmills@gmail.com}\\
ORCID: \href{https://orcid.org/0000-0003-0003-0552}{0000-0003-0003-0552}}
\date{11 August 2026}
\maketitle

\begin{abstract}
Szemer\'edi's theorem takes positive upper density as its hypothesis; the
Erd\H{o}s--Tur\'an conjecture takes the divergence of $\sum 1/a_n$. The second
hypothesis is strictly weaker, so a theorem proving the first does not settle a
conjecture assuming the second.

The implication that holds is elementary: a set with at least $\varepsilon N$
elements below $N$ contributes at least $\varepsilon$ to the reciprocal sum over
that range. The implication that fails is separated by the primes, whose
reciprocal sum diverges while their density is zero. For three-term progressions
both hypotheses are settled --- Roth's theorem for density, Bloom and Sisask for
the reciprocal sum --- and Behrend's construction shows that Roth's decay admits
no power saving. For $k \ge 4$ the conjecture is open.
\end{abstract}

\section{The two hypotheses}

Let $A = \{a_1 < a_2 < \cdots\} \subseteq \mathbb{N}$.

\begin{itemize}
\item[] \textbf{(D)} \quad
$\displaystyle \limsup_{N} \frac{|A \cap [0,N)|}{N} > 0$.
\item[] \textbf{(R)} \quad
$\displaystyle \sum_n \frac{1}{a_n} = \infty$.
\end{itemize}

\begin{proposition}
\label{prop:implies}
Hypothesis (D) implies hypothesis (R).
\end{proposition}

\begin{proof}
The finite form suffices: if $A \cap [0,N)$ has at least $\varepsilon N$
elements, then those elements contribute at least
\[
  \varepsilon N \cdot \frac1N \;=\; \varepsilon
\]
to $\sum_{a \in A,\ a < N} 1/a$, since each is at most $N$. Applying this along a
sequence of scales $N_1 < N_2 < \cdots$ on which the density stays above
$\varepsilon$, and which grows fast enough that the ranges are disjoint, gives
divergence.
\end{proof}

\begin{proposition}
\label{prop:strict}
The implication is strict: the primes satisfy (R) and fail (D).
\end{proposition}

\begin{proof}
$\sum_p 1/p$ diverges, while $\pi(N)/N \to 0$.
\end{proof}

\[
  \boxed{\;\text{(D)} \Longrightarrow \text{(R)}, \qquad
  \text{(R)} \nRightarrow \text{(D)}. \;}
\]

Szemer\'edi's theorem and the Erd\H{o}s--Tur\'an conjecture are therefore
different statements, and the latter is the stronger.

\section{Three terms, under density}

\begin{theorem}[Roth]
\label{thm:roth}
For every $\varepsilon > 0$ there is $N_0(\varepsilon)$ such that any
$A \subseteq [0,N)$ with $|A| \ge \varepsilon N$ and $N \ge N_0$ contains three
distinct elements in arithmetic progression.
\end{theorem}

\begin{corollary}
\label{cor:density}
Writing $r_3(N)$ for the size of the largest progression-free subset of
$[0,N)$, we have $r_3(N) = o(N)$.
\end{corollary}

\begin{theorem}[Behrend]
\label{thm:behrend}
\[
  r_3(N) \;\ge\; N \exp\!\big(-4\sqrt{\log N}\,\big).
\]
\end{theorem}

\begin{corollary}
The decay in \Cref{cor:density} is slower than any power of $N$: there is no
$\delta > 0$ with $r_3(N) = O(N^{1-\delta})$.
\end{corollary}

\begin{proof}
$\exp(-4\sqrt{\log N})$ exceeds $N^{-\delta} = \exp(-\delta \log N)$ for large
$N$, since $4\sqrt{\log N} < \delta \log N$ once $\log N > (4/\delta)^2$.
\end{proof}

Behrend's construction places points on a sphere in a high-dimensional grid,
where convexity forbids a midpoint; the dimension is tuned against the side
length, and that is where $\sqrt{\log N}$ enters.

\section{Three terms, under divergence}

The case $k = 3$ of the Erd\H{o}s--Tur\'an conjecture --- that (R) forces a
three-term progression --- is a theorem of Bloom and Sisask, whose bound
\[
  r_3(N) \;\ll\; \frac{N}{(\log N)^{1+c}}
\]
crosses the threshold at which the reciprocal sum of a progression-free set must
converge. No case $k \ge 4$ is known.

\section{Position}

\begin{center}
\begin{tabularx}{0.9\textwidth}{@{}lXX@{}}
\toprule
 & \textbf{hypothesis (D)} & \textbf{hypothesis (R)} \\
\midrule
$k = 3$   & Roth        & Bloom--Sisask \\
$k \ge 4$ & Szemer\'edi & open \\
\bottomrule
\end{tabularx}
\end{center}

Furstenberg's ergodic proof and Gowers's quantitative proof both establish the
(D) column. Green and Tao established progressions in the primes, which is a
statement about one specific set of density zero rather than about hypothesis (R)
in general.

\section{Verification}

Roth's theorem, its asymptotic form and Behrend's bound are instantiated from
Mathlib, and the divergence of the reciprocal sum over the primes together with
the finite density estimate are formalised alongside them; all depend on
\texttt{propext}, \texttt{Classical.choice} and \texttt{Quot.sound}.

\begin{thebibliography}{9}
\bibitem{ErdosTuran1936} P.~Erd\H{o}s and P.~Tur\'an, \emph{On some sequences of
integers}, J.\ London Math.\ Soc.\ \textbf{11} (1936), 261--264.

\bibitem{Roth1953} K.~F.~Roth, \emph{On certain sets of integers}, J.\ London
Math.\ Soc.\ \textbf{28} (1953), 104--109.

\bibitem{Behrend1946} F.~A.~Behrend, \emph{On sets of integers which contain no
three terms in arithmetical progression}, Proc.\ Nat.\ Acad.\ Sci.\ USA
\textbf{32} (1946), 331--332.

\bibitem{Szemeredi1975} E.~Szemer\'edi, \emph{On sets of integers containing no
$k$ elements in arithmetic progression}, Acta Arith.\ \textbf{27} (1975),
199--245.

\bibitem{BloomSisask} T.~F.~Bloom and O.~Sisask, \emph{Breaking the logarithmic
barrier in Roth's theorem on arithmetic progressions}, preprint,
arXiv:2007.03528.

\bibitem{GreenTao2008} B.~Green and T.~Tao, \emph{The primes contain arbitrarily
long arithmetic progressions}, Ann.\ of Math.\ \textbf{167} (2008), 481--547.
\end{thebibliography}

\end{document}

